CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, place TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', portfolio TEXT NOT NULL DEFAULT '', visible INTEGER NOT NULL DEFAULT 0, available INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS creator_specialties(owner TEXT PRIMARY KEY REFERENCES members(id) ON DELETE CASCADE, labels TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS links(token TEXT PRIMARY KEY,email TEXT NOT NULL,name TEXT NOT NULL,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,title TEXT NOT NULL, brief TEXT NOT NULL,due TEXT NOT NULL,budget TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS creator_work(owner TEXT PRIMARY KEY REFERENCES members(id) ON DELETE CASCADE, items TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS creator_enquiries(
 id TEXT PRIMARY KEY, creator_id TEXT NOT NULL, creator_name TEXT NOT NULL,
 client_name TEXT NOT NULL, email TEXT NOT NULL, brief TEXT NOT NULL,
 created BIGINT NOT NULL, handed_off BIGINT
);

CREATE TABLE IF NOT EXISTS creator_avatars(owner TEXT PRIMARY KEY REFERENCES members(id) ON DELETE CASCADE, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires BIGINT NOT NULL);
